const resp = $input.first().json;
const leads = Array.isArray(resp?.leads) ? resp.leads : [];
return leads.map(l => ({ json: l }));

// Build the Claude request body from the lead context. Keeping this
// out of the HTTP node's jsonBody expression because nested template
// literals + escaped quotes inside an n8n expression are fragile.

const lead = $input.first().json;
const person = lead.person || {};
const owner = lead.owner || {};
const scoring = lead.scoring || {};
const activities = (lead.recent_activities || [])
  .map(a => `- ${a.title}: ${(a.comment || '').substring(0, 300)}`)
  .join('\n');

const systemPrompt = [
  'You are a sales analyst preparing a one-page pre-call brief for an Underwings principal who is about to take a discovery call.',
  '',
  'Underwings is a UAE cybersecurity services company (Abu Dhabi, launched 2026). 3 named principals:',
  '- Manoj: GRC, ISO 27001 Lead Auditor, healthcare ADHICS v2',
  '- Nelson: offensive security (pen testing, OSCP, CEH)',
  '- Vinoth: network/infrastructure security (CCNP, Fortinet, Azure)',
  '',
  'Services: pen tests AED 9K-150K, ISO/ADHICS implementations, awareness training, PTaaS (AED 6K/mo), Continuous Compliance (AED 4K/mo), software resale (Sophos/Fortinet/etc).',
  '',
  'Primary 2026 vertical bet: Healthcare + ADHICS v2.',
  '',
  'Reply with a complete HTML email body — no markdown, no fences, no <html>/<head> tags (just the body content). Keep it under 350 words. Structure:',
  '<h2>Pre-call brief — {Name} / {Company}</h2>',
  '<p><strong>Meeting:</strong> {time} · <a href="{join_url}">Join link</a></p>',
  '<h3>Who you are meeting</h3><p>...</p>',
  '<h3>Why this lead exists</h3><p>...</p>',
  '<h3>Suggested talk track (3 questions)</h3><ul><li>...</li><li>...</li><li>...</li></ul>',
  '<h3>Recommended first offer</h3><p>e.g. "ADHICS v2 Gap Assessment from AED 35K"</p>',
  '<h3>Watch-outs</h3><p>...</p>',
  '',
  'Be specific and useful. Do not hedge. If info is sparse, say so and recommend probing questions.'
].join('\n');

const userMessage = [
  'Lead context:',
  '',
  `Person: ${person.name || 'unknown'} <${person.email || 'no-email'}>`,
  `Company: ${person.company || 'unspecified'}`,
  `Job title: ${person.job_title || 'unspecified'}`,
  `Phone: ${person.phone || 'none'}`,
  '',
  `Meeting: ${lead.next_meeting_at}`,
  `Join URL: ${lead.next_meeting_join_url || 'n/a'}`,
  `Deal title in CRM: ${lead.title}`,
  '',
  `AI score: ${scoring.score ?? 'not scored'}/100`,
  `Segment: ${scoring.segment || 'unknown'}`,
  '',
  `Assigned to: ${owner.name} <${owner.email}>`,
  '',
  'Recent CRM activities (most recent first):',
  activities || '(none)',
].join('\n');

return {
  body: {
    model: 'claude-sonnet-4-6',
    max_tokens: 1500,
    system: systemPrompt,
    messages: [{ role: 'user', content: userMessage }],
  },
  // Pass through context for downstream nodes
  lead,
};

const claudeResp = $input.first().json;
const lead = $('Build Claude request').first().json.lead;

// Bail if Claude failed (lead stays unbriefed -> retried next sweep)
if (!claudeResp || !claudeResp.content || !Array.isArray(claudeResp.content)) {
  return [];
}

let html = (claudeResp.content[0]?.text || '').trim();
// Strip accidental fences if Claude added them
html = html.replace(/^```(?:html)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
if (!html) return [];

// Wrap in a minimal styled shell for email-client friendliness
const styled = `<!doctype html><html><body style="margin:0;padding:24px;font-family:-apple-system,Segoe UI,sans-serif;color:#111;background:#f7f7f7"><table width="600" cellpadding="0" cellspacing="0" style="background:#fff;border-radius:8px;padding:24px;margin:0 auto"><tr><td>${html}<hr style="border:none;border-top:1px solid #eee;margin:24px 0"/><p style="font-size:12px;color:#888;margin:0">Generated automatically 30 min before your call · <a href="https://crm.underwings.org/admin/leads/view/${lead.lead_id}" style="color:#888">Open lead in Krayin →</a></p></td></tr></table></body></html>`;

const startsAt = lead.next_meeting_at;
const subject = `Brief: ${lead.person?.name || 'Unknown'}${lead.person?.company ? ' / ' + lead.person.company : ''} — call at ${startsAt}`;

return [{
  json: {
    lead_id: lead.lead_id,
    to:      lead.owner?.email,
    to_name: lead.owner?.name,
    subject,
    html: styled,
  }
}];
